'use strict';
// Deterministic, browser-local templates. No model, API, credentials or network calls.
function localProfile(v){
  const source=[v.refTitle,v.refBody,v.details].join(' ').toLowerCase();
  const profiles=[
    {match:/skincare|skin care|skin barrier|serum|moisturi|护肤|精华|面霜|皮肤/,name:'skincare essentials',topic:'Your everyday skincare ritual',hero:'A little care. A brighter everyday.',focus:'a considered approach to your daily skincare routine',terms:['Skincare Essentials','Everyday Skincare','Daily Care Collection','Skincare Routine','Personal Care Essentials']},
    {match:/clothing|apparel|dress|shirt|fashion|服装|服饰|连衣裙|穿搭/,name:'clothing and everyday style essentials',topic:'Making room for personal style',hero:'Everyday style, on your terms.',focus:'personal style, considered choices, and everyday dressing',terms:['Everyday Clothing','Style Essentials','Clothing Collection','Everyday Outfits','Personal Style']},
    {match:/jewelry|jewellery|necklace|earring|珠宝|首饰|项链|耳环/,name:'jewelry and personal accessories',topic:'The details that feel like you',hero:'Small details. Your own expression.',focus:'personal expression through jewelry and accessories',terms:['Jewelry Collection','Everyday Accessories','Personal Style Jewelry','Jewelry Essentials','Thoughtful Accessories']},
    {match:/furniture|home decor|bedding|家居|家具|床品|装饰/,name:'home and living essentials',topic:'A home that fits your life',hero:'Make room for everyday comfort.',focus:'thoughtful choices for the spaces you use every day',terms:['Home Essentials','Home and Living','Everyday Home Collection','Comfortable Living','Home Details']},
    {match:/electronics|headphone|charger|gadget|电子|耳机|充电/,name:'everyday technology accessories',topic:'Technology with a place in your day',hero:'Useful details for everyday life.',focus:'practical product choices that fit your everyday routines',terms:['Technology Accessories','Everyday Tech','Practical Accessories','Tech Essentials','Everyday Collection']},
    {match:/makeup|cosmetic|lipstick|beauty|彩妆|美妆|口红/,name:'beauty essentials',topic:'Beauty at your own pace',hero:'Your routine. Your kind of beautiful.',focus:'personal expression and a considered beauty routine',terms:['Beauty Essentials','Everyday Beauty','Beauty Collection','Personal Beauty Routine','Beauty Favorites']}
  ];
  const profile=profiles.find(p=>p.match.test(source))||{name:'everyday essentials',topic:'Thoughtful choices for everyday life',hero:'Good things for your everyday.',focus:'useful choices, personal preferences, and everyday enjoyment',terms:['Everyday Essentials','Thoughtful Finds','Everyday Collection','Practical Favorites','Personal Essentials']};
  const featureRules=[[/hydrat|moisturi|保湿|补水/,'hydration'],[/skin barrier|屏障/,'skin barrier care'],[/dewy|glow|光泽|水光/,'a dewy-looking finish'],[/soft|柔软/,'a soft feel'],[/lightweight|轻盈|轻便/,'a lightweight feel'],[/minimal|简约/,'a simple aesthetic'],[/comfort|舒适/,'everyday comfort']];
  return {...profile,features:featureRules.filter(([re])=>re.test(source)).map(([,text])=>text)};
}
function seasonalLine(date){
  if(!date)return 'A little something for your everyday';
  const [year,month,day]=date.split('-').map(Number);
  if(month===12&&day<=25)return 'A little holiday joy';
  if(month===1&&day<=7)return 'A fresh start for the new year';
  if(month===2&&day<=14)return 'A little love for your everyday';
  if(month===6&&day>=21||month===7&&day<=4)return 'A little summer celebration';
  if(month===10&&day>=15)return 'A little autumn treat';
  // Thanksgiving: fourth Thursday in November, calculated locally for the chosen year.
  const thanksgiving=1+(4-new Date(year,10,1).getDay()+7)%7+21;
  if(month===11&&day>=thanksgiving-14&&day<=thanksgiving+4)return 'A season of little thank-yous';
  return month>=3&&month<=5?'A fresh moment for spring':month>=6&&month<=8?'A little more summer joy':month>=9&&month<=11?'Settle into the season':'A little comfort for the season';
}
function generateLocal(v){
  const e=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])).replace(/[【】]/g,'');
  const profile=localProfile(v),product=profile.name;
  const paragraph=t=>`<p>${t}</p>`;
  const section=(heading,...paragraphs)=>`<h2>${heading}</h2>${paragraphs.map(paragraph).join('')}`;
  const contact=v.email?`Contact us at <a href="mailto:${e(v.email)}">${e(v.email)}</a>.`:'Please visit our <a href="/pages/contact-us">Contact Us page</a> for assistance.';
  const dated=v.date?paragraph(`Last updated: ${e(v.date)}.`):'';
  const about=section('Thoughtful choices for everyday life',`Everyday life is made up of small choices: what we reach for, what we make time for, and what feels right for us. Our approach centers on ${profile.focus}. We want shopping for ${product} to feel approachable, with room to explore your preferences and make decisions at your own pace. This is a place for people who appreciate the little details and want the practical side of shopping to feel just as considered as the products themselves.`)
  +section(profile.topic,`Our collection centers on ${product}. ${profile.features.length?`The product direction you will find here includes ${profile.features.join(', ')}. Specific details belong to the individual product description, so you can see which features apply to the item you are considering.`:'We encourage you to explore the individual product descriptions to understand the features, options, and intended uses of each item.'} A category can introduce you to a collection, but it cannot tell the whole story of how a product will fit your life. Your preferences, existing routine, and reason for shopping all matter. Take those details with you as you browse, and choose the options that answer your own needs.`)
  +aboutChapters.map(([heading,text])=>section(heading,text.replaceAll('{product}',product))).join('')
  +section('A clear view of the practical details',`Our store uses USD. Orders are dispatched in 1–3 days, with expected delivery in 6–12 days. Delivery timing is an estimate, so please allow room for the journey when planning a purchase. We provide worldwide free shipping and cover related duties and taxes, so customers do not need to bear those additional charges. Our return window is 60 days, and refunds take 5–10 days. The dedicated policy pages explain these commitments in the context of ordering, delivery, and returns. Keeping the practical information close at hand helps you decide with a clearer understanding of the purchase.`)
  +section('You are welcome here',`Whether this is your first visit or you are coming back to consider a favorite, thank you for taking the time to explore our collection. We hope you find ${product} that make sense for your life and feel enjoyable to choose. Browse slowly, read the details that matter to you, and make a decision that feels comfortable. Questions are welcome at any stage. ${contact} Your next purchase can begin with a simple question, a useful detail, or an idea you want to explore. We are glad to be part of that process.`);
  const pages=[
    {handle:'about-us',title:'About Us',body_html:about},
    {handle:'customer-service-policy',title:'Customer Service Policy',body_html:dated+section('How we can help',`Our customer service team can help with product questions, order details, delivery concerns, and returns. ${contact} Include your order number when asking about an existing purchase, together with a short description of what you need. Please do not send passwords or complete payment card details.`)+section('Before placing an order','Read the product description and review the options you have selected. If an item detail is unclear, ask before purchasing so that you can make an informed choice. All store prices and transactions use USD.')+section('Order changes','If you need to correct an address, change an order, or request cancellation, contact us as soon as possible. Whether a change is possible depends on the current order status. A request alone does not confirm that the order has been changed; wait for a response confirming the outcome.')+section('Delivery assistance','Orders are dispatched in 1–3 days, and expected delivery is 6–12 days. Worldwide shipping is free, and we cover related duties and taxes so customers do not bear additional charges. Delivery timing is estimated. If your parcel appears delayed, missing, or damaged, provide your order number and the details available so we can help review the issue.')+section('Returns and refunds','We offer a 60-day return window. Contact us for the return instructions applicable to your order before sending a parcel. Refunds take 5–10 days. See our Refund Policy for more information.')+section('Feedback',`Questions and feedback help us understand your experience. Tell us what happened and what assistance you are looking for. ${contact}`)},
    {handle:'privacy-policy',title:'Privacy Policy',body_html:dated+section('Your information and your order',`This policy explains how customer information is used when you browse our store, place an order, or contact us for assistance. When you place an order or contact us, the information you provide may include your name, contact details, delivery address, order selections, and the content of your message. Share only the details needed for your purchase or request.`)+section('Order and service information','Order information is used to arrange your purchase, delivery, and related customer assistance. Contact information allows us to respond to questions about an order, a delivery, or a return. Information relevant to a payment or delivery may need to be processed by the services involved in completing that transaction.')+section('Information in your messages','If you contact us about a problem, an order number and a clear description can help identify the relevant purchase. Avoid including passwords, complete payment card numbers, or other details that are not needed to answer your question. If more information is necessary, we can explain what would help with the request.')+section('Keeping your details accurate','Please check the information you enter before submitting an order. If you notice an incorrect contact or delivery detail, contact us promptly and explain the correction. The stage of order processing may affect whether a delivery detail can still be changed.')+section('Questions about your information',`If you want to ask about the information connected with your purchase, request a correction, or discuss removal of information, please contact us with enough detail to identify your request. ${contact}`)},
    {handle:'refund-policy',title:'Refund Policy',body_html:dated+section('Our return window',`We offer a 60-day return window. If you would like to return an item, contact us with your order number and the items involved. We will explain the next steps for your order. ${contact}`)+section('Before sending a return','Please obtain the return instructions and destination for your order before sending a parcel. This helps the return reach the appropriate destination and allows it to be associated with your purchase. Keep the dispatch confirmation and any tracking information available for your reference.')+section('Problems with an item','If an item arrives damaged, incorrect, or with a problem, describe what happened and identify the affected item. Clear photos can help explain a visible issue when available. We can then review the concern and discuss the appropriate next steps with you.')+section('Refund timing','Refunds take 5–10 days. If you have a question about a refund or cannot identify it in your payment account, contact us with your order number and any relevant confirmation. All store transactions use USD.')+section('Questions before returning','If you are unsure about the condition of an item, return arrangements, or the status of a refund, ask before taking the next step. The instructions for your order will help you understand how to proceed. Do not assume that a different order or an address on the original parcel has the same return arrangements.')},
    {handle:'shipping-policy',title:'Shipping Policy',body_html:dated+section('Order dispatch','Orders are dispatched in 1–3 days. Please check your order details and delivery address carefully when placing the order. If you discover an error, contact us as soon as possible so we can review whether a correction is still possible.')+section('Estimated delivery','Expected delivery is 6–12 days. This is an estimate, and the actual arrival time may be affected by the delivery journey. Please take the estimated timing into account when ordering for a particular occasion. We do not promise a guaranteed arrival date.')+section('Duties and related charges','We cover related duties and taxes so customers do not need to bear these additional charges. If you receive a request for a charge connected with your delivery, contact us with the order number and the notice so that we can review it.')+section('Tracking and delivery questions','Refer to the delivery information provided for your order. If the available tracking appears delayed or the parcel has not arrived as expected, contact us with your order number and the latest information you have. If a parcel is marked delivered but cannot be located, explain the situation so we can assist with reviewing it.')+section('Address changes and parcel issues',`Address changes depend on the current stage of processing and delivery. If a parcel arrives damaged or an item is missing, keep the packaging and describe the issue when contacting us. ${contact}`)},
    {handle:'terms-of-purchase',title:'Terms of Purchase',body_html:dated+section('Placing an order',`Before placing an order, review the product description, selected options, quantity, contact information, and delivery address. Keep your order confirmation for reference. If something in the confirmation appears incorrect, contact us promptly.`)+section('Prices and currency','Our store uses USD. Review the amount shown for your purchase at checkout. Promotions apply as displayed with the relevant offer; check the product and checkout details to understand the amount associated with the items you select.')+section('Dispatch and delivery','Orders are dispatched in 1–3 days, with expected delivery in 6–12 days. Delivery times are estimates. We provide worldwide free shipping and cover related duties and taxes, so customers do not bear those additional charges.')+section('Order changes','Contact us as soon as possible if you need to request an order change or cancellation. Availability of a change depends on the status of the order. Wait for confirmation of the outcome rather than assuming a request has already taken effect.')+section('Returns and refunds','We offer a 60-day return window, and refunds take 5–10 days. Contact us for instructions for your order before returning an item. Our Refund Policy provides further information about requesting assistance and following the return process.')+section('Purchase assistance',`If you have a question about an item, a payment associated with an order, delivery, or a return, include your order number when available. ${contact}`)},
    {handle:'terms-of-use',title:'Terms of Use',body_html:dated+section('Using our website',`These terms describe how to use our online store. You can browse products, review store information, and place orders through this website. Please use the site in a way that respects other visitors, the store, and the services needed to keep it working.`)+section('Product and website information','Read the information for the specific item you are considering. General collection descriptions introduce a category; the product description provides the details relevant to that item. If something appears unclear or inconsistent, ask us for clarification before purchasing.')+section('Your details and account','Provide accurate details when placing an order or sending a request. If you use a customer account, keep your sign-in information private and avoid sharing it through ordinary support messages. Contact us if you need help with the details associated with an order.')+section('Appropriate use','Do not attempt to interfere with the operation of the website, access information that is not intended for you, or submit misleading or harmful material. Keep messages relevant to the assistance or information you are requesting.')+section('Orders and policies','Purchases are described in our Terms of Purchase. Delivery and return information is available in our Shipping Policy and Refund Policy. Please consult those pages for the practical details of ordering from the store.')+section('Questions and corrections',`If a link is not working, a description needs clarification, or you notice a problem while using the website, tell us which page you were viewing and what happened. ${contact}`)}
  ];
  const prefix=seasonalLine(v.date),features=profile.features.length?profile.features.join(', '):profile.focus;
  const brandLabel=(v.brand||'').trim(),fromBrand=brandLabel?` from ${brandLabel}`:'',seoBrand=brandLabel?` | ${brandLabel}`:'';
  const marketing={announcements:['A little closer, wherever you are — free worldwide shipping.',`${prefix} — enjoy up to ${v.discount}% off.`],hero:{title:profile.hero,description:`Discover ${product}${fromBrand}, with ${features}.`,cta:'Explore the collection'},placements:[{location:'Top announcement bar — alternate the two messages',copy:'Show one announcement at a time, with a readable rotation interval.'},{location:'Homepage hero — above the main collection',copy:`${profile.hero} Explore ${product}${fromBrand}.`},{location:'Below the featured collection',copy:`Your favorites, within reach. Enjoy up to ${v.discount}% off and free worldwide shipping.`},{location:'Above the footer — service reassurance',copy:'1–3-day dispatch · Estimated 6–12-day delivery · 60-day returns · USD'}],seo:profile.terms.map((term,i)=>({title:`${term}${seoBrand}`,description:`Explore ${i===0&&profile.features.length?profile.features.join(', ')+' and ':''}${product}${fromBrand}. Browse product details and find options for your everyday routine.`})),review_notes:['Generated locally from built-in templates and keyword matching. Review product-specific statements against your actual catalog.','Confirm the privacy description matches your store’s actual information handling.','Contact Us retains the supplied form, which only redirects to the homepage and does not send a message.']};
  return {pages,marketing};
}

const aboutChapters=[
['A place for everyday choices',`We think the most useful starting point is your own life. Before an item becomes part of your day, there is a small decision about what you need, what you enjoy, and what you already own. Our approach to {product} begins with that decision. We want you to feel welcome whether you arrive with a specific idea or are simply exploring what might work for you. There is no single routine that everyone needs to follow. What matters is finding a choice that feels considered in the context of your own preferences. A satisfying purchase can be a familiar favorite, a useful replacement, or something new that you have taken time to understand.`],
['Your preferences belong in the conversation',`Personal preferences are often found in details that a broad trend cannot explain. You may notice the way something feels, the place it takes in your routine, or how easily you can imagine using it. Those observations are worth taking seriously. Keep those preferences in mind as you explore the products available in our store. A popular choice is one source of inspiration, but your own priorities are part of the decision too. Read the description with those priorities in mind, compare the available options, and pause if an important question remains unanswered. Feeling comfortable with the information in front of you is a useful part of choosing something you will enjoy.`],
['Small moments deserve attention',`The everyday can seem ordinary until we pay closer attention to it. A few minutes of preparation, an item within easy reach, or a familiar step at the end of a busy day can change the feeling of a routine. We like the idea of making room for those moments without turning them into another obligation. Products can have a place in a pleasant experience, but the experience is still yours to shape. Choose what is useful, decide what feels comfortable, and let the rest follow naturally. Our interest in {product} is connected to that quieter kind of enjoyment: the details that fit into real life and make an ordinary moment feel a little more considered.`],
['A collection is a starting point',`Browsing a collection is a chance to discover possibilities. It can help you notice a category you had not considered or compare options you already know you need. We see that first look as the beginning of a decision, rather than the whole decision itself. Once an item catches your attention, its individual description becomes the most useful place to continue. Check the features, options, and other details that apply to that product. Think about how those details relate to your own reason for shopping. A collection introduces the overall direction of a store; a particular item earns its place in your life through the more specific questions you ask about it.`],
['Clarity makes browsing more comfortable',`A good shopping experience leaves space to understand what is being offered. You should be able to look at a product, read its description, and consider the details that matter to your choice. We value clear language because it helps make that process less tiring. If a description raises a question, there is no need to rush past it. Seeking clarification is a sensible part of shopping, especially when an unfamiliar item is involved. You are welcome to ask questions and compare options before deciding what suits you. Confidence grows from useful information and realistic expectations, one detail at a time.`],
['A routine can be personal and flexible',`Daily life rarely follows exactly the same pattern every day. Some mornings allow more time, some evenings ask for simplicity, and some weeks change your usual priorities. We believe the things you choose should be considered with that flexibility in mind. An item may have one place in a quiet routine and another in a busier moment. Thinking about those situations can help you decide what is useful to you. You do not need to build an elaborate routine around every purchase. Sometimes the most welcome addition is the one that feels easy to understand and has a clear role alongside the things you already use and enjoy.`],
['Value starts with relevance',`Price is an important part of a purchase, and value also depends on whether the item answers a real preference or need. Something can be attractive on a screen and still require a moment of thought about where it belongs in your life. We encourage that moment. Consider why you are interested, how you expect to use the item, and whether the available description supports that expectation. The answer will be different for different people. For us, value includes both the usefulness of a product and a clear understanding of the purchase terms. Knowing the currency, delivery estimate, and return window helps you see the decision more completely.`],
['Make room for your own pace',`There is no ideal speed for making a decision. Some customers know exactly what they want and appreciate a straightforward route to the item. Others like to explore, return to a page, and compare a few possibilities before choosing. Both approaches belong here. Take the time that helps you feel informed. If you are shopping during a promotion, read the offer alongside the product information rather than allowing the offer to become the entire reason for the purchase. A decision that fits your own priorities can remain satisfying after the moment of browsing has passed. We welcome the thoughtful pauses as much as the excitement of discovering something new.`],
['Enjoyment does not need an occasion',`A special date can be a lovely reason to choose something, but everyday enjoyment has a place too. You might be refreshing a familiar routine, replacing an item, or giving attention to a small detail you have been meaning to consider. Those ordinary reasons are enough. We like products to be part of a life that is already happening, with all of its quiet moments and changing plans. You do not have to wait for a perfectly arranged day to appreciate something useful or pleasant. The connection between a product and your life often begins in the simple recognition that it could have a welcome place in an ordinary moment.`],
['The details behind a decision',`When you compare two items, it helps to identify the detail that will actually make a difference to you. It may be an available option, an intended use, or information about how the product fits with something you already have. Looking for that distinction can make browsing more purposeful. It also helps separate a general impression from a specific reason to choose. We encourage you to use product descriptions as a practical resource, not simply as words to pass over before checkout. If the detail you need is missing, ask about it. A clear answer to one important question can be more useful than a long list of impressions that do not relate to your needs.`],
['A little curiosity is welcome',`Trying something unfamiliar can begin with curiosity rather than certainty. You may be interested in a different kind of product or a new way to approach a familiar routine. We welcome that interest while encouraging you to keep your expectations connected to the information available. Learn what the item is intended for, look at its specific features, and think about how you would introduce it into your day. You can explore without assuming that every new discovery needs to become a purchase. The process of learning your own preferences has value in itself. When you do find something that makes sense, the decision can feel more personal because you have taken time to understand it.`],
['Familiar favorites have a place too',`Discovery is only one part of shopping. Sometimes you are looking for something that fits an already familiar pattern, and the comfort of that familiarity is part of its appeal. You may know the category you prefer or the role an item needs to play. Even then, reviewing the details of the particular product is worthwhile. Options and descriptions can differ, and a familiar appearance does not answer every practical question. Whether you arrive with a specific need or simply want to explore, we aim to make the information you need easy to find. A considered purchase does not have to be surprising; it can simply be a choice that feels right for the life you already know.`],
['What you already own matters',`A new item enters a context. You may have products you love, habits you want to keep, or limited space for something additional. Those facts can be useful guides when browsing {product}. Consider whether the item fills a gap, replaces something, or adds an option you would use. There is no requirement to start over in order to enjoy a new choice. In many cases, thinking about what you already have makes the decision clearer. It can also help you identify the features that deserve closer attention. We like the idea of shopping as a thoughtful addition to your own life, with respect for the preferences and routines that are already part of it.`],
['Inspiration should leave room for you',`A photograph, a collection, or a description can offer an idea, but you are the person who decides what to do with that idea. The way an item fits your day may be different from the way someone else imagines it. That difference is part of personal taste. We hope the experience of browsing our store gives you useful starting points while leaving room for your own interpretation. You do not need to reproduce an entire look or routine to appreciate a single detail. Take the part that speaks to your preferences, understand the product behind it, and decide whether it deserves a place among the things you choose for yourself.`],
['Practical questions are good questions',`An attractive item can still prompt a very practical question. How will it fit into the way you use things? Which option is relevant? What should you check before ordering? Those questions are not interruptions to the shopping experience; they are part of making the experience useful. We encourage you to bring them forward when the description does not provide the answer you need. It is better to understand an important detail before choosing than to rely on an assumption. Our customer service information is there to help you find the next step when a question arises, whether you are still considering a product or asking about an order you have already placed.`],
['Shopping can feel calm',`There is something appealing about having enough room to look, read, and decide. Our aim is to offer a welcoming place to browse and make informed choices at your own pace. You can begin with a category, narrow your attention to a few items, and return to the details that matter. There is no need to make every choice feel like a major event. Sometimes a calm process produces the clearest answer: this is useful to me, this is worth asking about, or this is not the right fit today. Each answer helps you understand your preferences. We hope the store feels like a place where those decisions can be made with a comfortable amount of attention.`],
['Every order has a practical journey',`A purchase continues beyond the moment you place it. There is an order to prepare, a parcel to dispatch, and a delivery journey to complete. Knowing the broad timing helps you plan with realistic expectations. Before ordering, take a moment to check the dispatch and delivery information and consider whether it fits the reason for your purchase. If you are shopping for a specific occasion, allow room for the fact that delivery is estimated. Keep your confirmation where you can find it, and use the order number when asking for assistance. These small practical steps help connect the excitement of choosing something with the information needed to follow its journey.`],
['The address deserves a second look',`One of the simplest useful habits at checkout is reviewing the delivery details. A complete address and accurate contact information help connect the order with the intended recipient. It is easy to overlook a small mistake when you are ready to finish a purchase, so a final check is worthwhile. If you do notice an error afterward, contact us promptly and explain what needs to change. Whether an adjustment is possible depends on the stage of the order. We include this practical reminder because a pleasant shopping experience is supported by details that may seem ordinary. The care you give to those details can matter just as much as the attention you give to choosing the item.`],
['Choosing something for another person',`Shopping for someone else adds another perspective to the decision. Their preferences, routines, and practical needs may differ from your own. Think about the details they would notice and the information that would help you choose on their behalf. A gift can be thoughtful because it reflects attention, even when the item itself is simple. Read the product description carefully, review the available options, and consider the delivery estimate if there is an occasion in mind. We encourage you to make those practical considerations part of the gesture. A little time spent understanding the recipient can turn browsing from a general search into a more personal and purposeful choice.`],
['A considered approach to promotions',`An offer can make an item more appealing, especially when you have already been considering it. We encourage you to read a promotion together with the details of the product and the amount shown at checkout. The best reason to choose remains the connection between the item and your own needs or preferences. A discount may support that decision, but it does not replace the information that helps you understand what you are buying. Take a moment to compare the selected option, quantity, and order total before submitting the purchase. Keeping those details in view lets you appreciate an offer while still making a choice that feels useful beyond the promotion itself.`],
['When a question comes after ordering',`It is normal for a question to arise after a purchase. You might need help understanding an update, correcting a detail, or working out the next step when something does not appear as expected. Start with your order confirmation and gather the information most closely connected with the issue. A concise description of what happened can make a request easier to understand. If a visible problem is involved, a clear description or relevant image may help explain it. There is no need to share private passwords or complete payment card details. The goal is to provide the information that connects the question with the order and helps the conversation move toward the appropriate next step.`],
['Room to reconsider',`A decision made online sometimes needs another look once the purchase becomes part of real life. Our return information is intended to give you a clear starting point when that happens. Read the policy and contact us for the instructions relevant to your order before sending an item. Keeping the order number and any return information together can make the process easier to follow. We believe the practical side of shopping should include an understandable route for asking about returns, just as it includes information about ordering and delivery. If you are unsure about an aspect of the process, ask about it rather than relying on an address or assumption from a different purchase.`],
['The value of a clear conversation',`Helpful communication often starts with a specific question. Tell us which item or order you are asking about and what you would like to understand. If there are several concerns, setting them out clearly can help keep the conversation focused. We also welcome feedback about the experience of browsing and finding information. A detail that was easy to miss may be the detail another customer needs too. Your experience is personal, and describing it in your own words is useful. Our customer service pages provide a starting point for those conversations, with practical guidance on orders, delivery, and returns. If you still need help, use the contact information provided to explain your question.`],
['Trust grows through realistic expectations',`We believe it is helpful to distinguish an idea that inspires you from a detail that you need to verify. A general description can introduce a collection, while an individual product page explains the item you are considering. Delivery information provides an estimate, and an order confirmation records what you selected. Each type of information has a role. Reading them together creates a more complete picture of the purchase. We encourage you to ask when those details do not answer an important question. A comfortable shopping relationship depends on understanding the practical facts, knowing where to seek clarification, and allowing the product to be considered on the basis of the information actually available.`],
['Your experience is your own',`People can choose the same product for different reasons. One person may be drawn to a particular detail, another may be solving a practical problem, and someone else may be exploring a new preference. We do not expect every customer to approach {product} with the same priorities. That variety is part of what makes personal choice interesting. Use descriptions and other available information to support your decision, while keeping your own circumstances in mind. A product does not need to mean the same thing to everyone in order to have a useful place in your life. What matters is whether the choice makes sense to you and whether your expectations are grounded in the details of the item.`],
['An invitation to notice what you enjoy',`Sometimes it helps to step back from the question of what is new and ask what you already enjoy. You may value simplicity, a familiar feeling, a practical detail, or the ease of having an item ready when you need it. Noticing that preference can make the next choice easier. It gives you a personal point of reference while you browse, rather than leaving every decision to a passing impression. We hope our store gives you space to make those connections. The process can be as simple as reading a description and recognizing a detail that matters to you. That small recognition is often where a thoughtful and satisfying purchase begins.`],
['Make the next step a comfortable one',`When you are ready to choose, review the specific item and the practical terms one more time. Confirm the option, the quantity, and the information needed to complete the order. If you are not ready, you can continue exploring with a clearer sense of what you want to know. We see both outcomes as part of a useful shopping experience. Our role is to present a collection and a route through the practical questions; your role is to decide what belongs in your life. We hope that division leaves you feeling comfortable, informed, and free to appreciate the products that fit your own priorities at the moment you are making the choice.`]
];
